export function App(props) {
  return (
    <main data-mode={props.mode} aria-label={props.label}>
      <h1>{props.title}</h1>
      {props.visible ? <p>{props.message}</p> : <p>hidden</p>}
      <ul>
        {props.items.map(item => (
          <li data-id={item.id}>{item.label}</li>
        ))}
      </ul>
      <svg viewBox="0 0 10 10" aria-label="shape">
        <circle cx={props.radius} cy="5" r="2" />
      </svg>
    </main>
  )
}

import { $state } from 'fict'

let increaseByTwo

export function App(props) {
  let count = $state(props.start)
  increaseByTwo = () => {
    count += 2
  }
  return (
    <article data-kind={props.kind}>
      <span>{props.prefix}:{count}</span>
      <button onClick={() => count++}>add</button>
      <input aria-label="count" value={count} />
    </article>
  )
}

export function advance() {
  increaseByTwo()
}

import { $state } from 'fict'

export function App(props) {
  let count = $state(props.start)
  return (
    <button data-kind={props.kind} onClick$={() => count++}>
      {props.label}:{count}
    </button>
  )
}

import { Suspense, createSuspenseToken } from 'fict'

const pending = createSuspenseToken()
let ready = false

function Deferred(props) {
  if (!ready) throw pending.token
  return <strong data-phase="ready">ready:{props.label}</strong>
}

export function release() {
  ready = true
  pending.resolve()
}

export function App(props) {
  return (
    <main>
      <h2>stream:{props.title}</h2>
      <Suspense fallback={<em data-phase="loading">loading:{props.label}</em>}>
        <Deferred label={props.label} />
      </Suspense>
      <footer>end</footer>
    </main>
  )
}
